          </div>
          {item.response.citations.length > 0 && (
            <div style={{ marginTop: '6px', fontSize: '11px', color: '#8888bb' }}>
              {item.response.citations.length} citation(s) | Confidence: {(item.response.confidence * 100).toFixed(0)}%
            </div>
