import { useState } from 'react';
import { Citation, FeedbackRating, QAHistory, QAResponse } from '../../shared/types';

interface Props {
  history: QAHistory[];
  /** Current rating per answer id. */
  ratings: Record<string, FeedbackRating>;
  onRate: (answerId: string, rating: FeedbackRating) => void;
  /** Question currently awaiting an answer, shown as a pending exchange. */
  pendingQuestion?: string | null;
}

/** Renders the full Q&A history as a chat-style conversation. */
export function ConversationHistory({ history, ratings, onRate, pendingQuestion }: Props) {
  if (history.length === 0 && !pendingQuestion) {
    return (
      <div style={{ color: '#666', textAlign: 'center', paddingTop: '40px' }} data-testid="conversation-empty">
        No questions yet. Ask something about your documents below.
      </div>
    );
  }

  return (
    <ol aria-label="Conversation history" style={{ listStyle: 'none', display: 'flex', flexDirection: 'column', gap: '14px' }}>
      {history.map((item, index) => (
        <li key={item.response.id ?? index} data-testid="conversation-exchange" style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
          <QuestionBubble text={item.question} />
          <AnswerBubble
            response={item.response}
            rating={ratings[item.response.id]}
            onRate={onRate}
          />
        </li>
      ))}
      {pendingQuestion && (
        <li style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
          <QuestionBubble text={pendingQuestion} />
          <div role="status" style={{ ...bubbleBase, alignSelf: 'flex-start', color: '#8888bb', fontStyle: 'italic' }}>
            Thinking…
          </div>
        </li>
      )}
    </ol>
  );
}

const bubbleBase: React.CSSProperties = {
  maxWidth: '85%',
  padding: '10px 14px',
  borderRadius: '12px',
  fontSize: '14px',
  lineHeight: 1.55,
};

function QuestionBubble({ text }: { text: string }) {
  return (
    <div
      data-role="user"
      style={{ ...bubbleBase, alignSelf: 'flex-end', background: '#533483', color: '#fff', borderBottomRightRadius: '4px' }}
    >
      {text}
    </div>
  );
}

function AnswerBubble({
  response,
  rating,
  onRate,
}: {
  response: QAResponse;
  rating: FeedbackRating | undefined;
  onRate: (answerId: string, rating: FeedbackRating) => void;
}) {
  return (
    <div
      data-role="assistant"
      data-answer-id={response.id}
      style={{
        ...bubbleBase,
        alignSelf: 'flex-start',
        background: '#1a1a3e',
        border: '1px solid #0f3460',
        borderBottomLeftRadius: '4px',
      }}
    >
      <div>{response.answer}</div>

      {response.citations.length > 0 && <CitationList citations={response.citations} />}

      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: '12px', marginTop: '10px', flexWrap: 'wrap' }}>
        <ConfidenceIndicator confidence={response.confidence} />
        <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
          <span style={{ fontSize: '11px', color: '#666' }}>
            {new Date(response.timestamp).toLocaleString()}
          </span>
          <FeedbackButton
            label="Mark answer helpful"
            symbol="👍"
            active={rating === 'up'}
            onClick={() => onRate(response.id, 'up')}
          />
          <FeedbackButton
            label="Mark answer not helpful"
            symbol="👎"
            active={rating === 'down'}
            onClick={() => onRate(response.id, 'down')}
          />
        </div>
      </div>
    </div>
  );
}

function CitationList({ citations }: { citations: Citation[] }) {
  return (
    <div style={{ marginTop: '10px' }}>
      <div style={{ fontSize: '11px', color: '#8888bb', fontWeight: 600, marginBottom: '4px' }}>
        Sources ({citations.length})
      </div>
      <ul style={{ listStyle: 'none', display: 'flex', flexDirection: 'column', gap: '4px' }}>
        {citations.map((c, i) => (
          <CitationItem key={`${c.documentId}-${c.chunkIndex}-${i}`} citation={c} />
        ))}
      </ul>
    </div>
  );
}

function CitationItem({ citation }: { citation: Citation }) {
  const [open, setOpen] = useState(false);
  return (
    <li style={{ borderLeft: '2px solid #533483', paddingLeft: '8px' }}>
      <button
        type="button"
        aria-expanded={open}
        onClick={() => setOpen(o => !o)}
        style={{
          background: 'none',
          border: 'none',
          color: '#b088f9',
          cursor: 'pointer',
          fontSize: '12px',
          padding: 0,
          textAlign: 'left',
        }}
      >
        {open ? '▾' : '▸'} {citation.documentTitle} · chunk {citation.chunkIndex}
      </button>
      {open && (
        <blockquote
          data-testid="citation-excerpt"
          style={{ marginTop: '4px', fontSize: '12px', color: '#c0c0d8', whiteSpace: 'pre-wrap', lineHeight: 1.5 }}
        >
          {citation.excerpt}
        </blockquote>
      )}
    </li>
  );
}

function ConfidenceIndicator({ confidence }: { confidence: number }) {
  const pct = Math.round(Math.max(0, Math.min(1, confidence)) * 100);
  const level = pct >= 70 ? 'High' : pct >= 40 ? 'Medium' : 'Low';
  const color = level === 'High' ? '#5cb85c' : level === 'Medium' ? '#f0ad4e' : '#d9534f';
  return (
    <div
      role="meter"
      aria-label="Answer confidence"
      aria-valuemin={0}
      aria-valuemax={100}
      aria-valuenow={pct}
      aria-valuetext={`${pct}% (${level})`}
      style={{ display: 'flex', alignItems: 'center', gap: '6px', fontSize: '11px', color: '#a0a0c0' }}
    >
      <div style={{ width: '60px', height: '6px', background: '#0f1729', borderRadius: '3px', overflow: 'hidden' }}>
        <div style={{ width: `${pct}%`, height: '100%', background: color }} />
      </div>
      <span>Confidence: {pct}% ({level})</span>
    </div>
  );
}

function FeedbackButton({
  label,
  symbol,
  active,
  onClick,
}: {
  label: string;
  symbol: string;
  active: boolean;
  onClick: () => void;
}) {
  return (
    <button
      type="button"
      aria-label={label}
      aria-pressed={active}
      title={label}
      onClick={onClick}
      style={{
        padding: '2px 8px',
        background: active ? '#533483' : 'transparent',
        border: `1px solid ${active ? '#b088f9' : '#0f3460'}`,
        borderRadius: '4px',
        cursor: 'pointer',
        fontSize: '13px',
      }}
    >
      {symbol}
    </button>
  );
}

