};

function QuestionBubble({ text }: { text: string }) {
  return (
    <div
      data-role="user"
      style={{ ...bubbleBase, alignSelf: 'flex-end', background: '#533483', color: '#fff', borderBottomRightRadius: '4px' }}
    >
      {text}
    </div>
  );
}

function AnswerBubble({
  response,
  rating,
  onRate,
}: {
  response: QAResponse;
  rating: FeedbackRating | undefined;
  onRate: (answerId: string, rating: FeedbackRating) => void;
}) {
  return (
    <div
      data-role="assistant"
      data-answer-id={response.id}
      style={{
        ...bubbleBase,
        alignSelf: 'flex-start',
        background: '#1a1a3e',
        border: '1px solid #0f3460',
        borderBottomLeftRadius: '4px',
      }}
    >
      <div>{response.answer}</div>

      {response.citations.length > 0 && <CitationList citations={response.citations} />}

      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: '12px', marginTop: '10px', flexWrap: 'wrap' }}>
        <ConfidenceIndicator confidence={response.confidence} />
        <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
          <span style={{ fontSize: '11px', color: '#666' }}>
            {new Date(response.timestamp).toLocaleString()}
          </span>
          <FeedbackButton
            label="Mark answer helpful"
            symbol="👍"
            active={rating === 'up'}
            onClick={() => onRate(response.id, 'up')}
          />
          <FeedbackButton
            label="Mark answer not helpful"
            symbol="👎"
            active={rating === 'down'}
            onClick={() => onRate(response.id, 'down')}
          />
        </div>
      </div>
    </div>
  );
}

function CitationList({ citations }: { citations: Citation[] }) {
