      </div>
      {history.map((item, index) => (
        <div key={index} style={{
          marginBottom: '16px',
          padding: '12px',
          background: '#1a1a3e',
          borderRadius: '6px',
          border: '1px solid #0f3460',
        }}>
          <div style={{ fontSize: '13px', fontWeight: 500, color: '#b088f9' }}>
            Q: {item.question}
          </div>
          <div style={{ fontSize: '13px', marginTop: '8px', lineHeight: 1.5 }}>
            {item.response.answer}
          </div>
