import { useEffect, useRef, useState } from 'react';
import { FeedbackRating, QAHistory } from '../../shared/types';
import { ConversationHistory } from './ConversationHistory';

interface Props {
  history: QAHistory[];
  ratings: Record<string, FeedbackRating>;
  onAsk: (question: string) => Promise<void>;
  onRate: (answerId: string, rating: FeedbackRating) => void;
  error?: string | null;
}

/** Question panel: the full conversation plus the input to ask the next question. */
export function QuestionPanel({ history, ratings, onAsk, onRate, error }: Props) {
  const [question, setQuestion] = useState('');
  const [pending, setPending] = useState<string | null>(null);
  const bottomRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    bottomRef.current?.scrollIntoView?.({ block: 'end' });
  }, [history.length, pending]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const q = question.trim();
    if (!q || pending) return;
    setQuestion('');
    setPending(q);
    try {
      await onAsk(q);
    } finally {
      setPending(null);
    }
  };

  return (
    <section aria-label="Questions" style={{ flex: 1, display: 'flex', flexDirection: 'column', minHeight: 0 }}>
      <div style={{ flex: 1, overflow: 'auto', padding: '16px 20px' }}>
        <ConversationHistory history={history} ratings={ratings} onRate={onRate} pendingQuestion={pending} />
        <div ref={bottomRef} />
      </div>

      {error && (
        <div role="alert" style={{ padding: '6px 20px', fontSize: '12px', color: '#ff8a80', background: '#2a1a2e' }}>
          {error}
        </div>
      )}

      <form
        onSubmit={handleSubmit}
        style={{
          display: 'flex',
          padding: '12px 20px',
          borderTop: '1px solid #0f3460',
          background: '#16213e',
        }}
      >
        <input
          type="text"
          aria-label="Question"
          value={question}
          onChange={e => setQuestion(e.target.value)}
          placeholder="Ask a question about your documents..."
          style={{
            flex: 1,
            padding: '10px 14px',
            background: '#1a1a2e',
            color: '#e0e0e0',
            border: '1px solid #0f3460',
            borderRadius: '6px',
            fontSize: '14px',
            outline: 'none',
          }}
        />
        <button
          type="submit"
          disabled={!!pending}
          style={{
            marginLeft: '10px',
            padding: '10px 20px',
            background: '#533483',
            color: '#fff',
            border: 'none',
            borderRadius: '6px',
            cursor: pending ? 'wait' : 'pointer',
            opacity: pending ? 0.6 : 1,
            fontSize: '14px',
            fontWeight: 500,
          }}
        >
          Ask
        </button>
      </form>
    </section>
  );
}

