import { useState, useCallback, useEffect, useMemo } from 'react';
import { DocumentList } from './components/DocumentList';
import { QuestionPanel } from './components/QuestionPanel';
import { DocumentDetail } from './components/DocumentDetail';
import { StatusBar } from './components/StatusBar';
import { ResetButton } from './components/ResetButton';
import { Document, AppStatus, FeedbackEntry, FeedbackRating, IndexStatus, QAHistory } from '../shared/types';

function toAppStatus(s: IndexStatus): AppStatus {
  return {
    documentsLoaded: s.totalDocuments,
    indexStatus: s.status,
    lastActivity: s.lastIndexed ?? '',
  };
}

const headerButton: React.CSSProperties = {
  padding: '6px 14px',
  background: '#0f3460',
  color: '#e0e0e0',
  border: '1px solid #1a1a4e',
  borderRadius: '4px',
  cursor: 'pointer',
  fontSize: '13px',
};

export function App() {
  const [documents, setDocuments] = useState<Document[]>([]);
  const [selectedDoc, setSelectedDoc] = useState<Document | null>(null);
  const [appStatus, setAppStatus] = useState<AppStatus>({
    documentsLoaded: 0,
    indexStatus: 'idle',
    lastActivity: '',
  });
  const [history, setHistory] = useState<QAHistory[]>([]);
  const [feedback, setFeedback] = useState<FeedbackEntry[]>([]);
  const [error, setError] = useState<string | null>(null);

  const ratings = useMemo(() => {
    const map: Record<string, FeedbackRating> = {};
    for (const f of feedback) map[f.answerId] = f.rating;
    return map;
  }, [feedback]);

  const refreshAll = useCallback(async () => {
    try {
      const [docs, status, hist, fb] = await Promise.all([
        window.knowledgeBase.documents.list(),
        window.knowledgeBase.indexing.status(),
        window.knowledgeBase.qa.history(),
        window.knowledgeBase.feedback.list(),
      ]);
      setDocuments(docs);
      setAppStatus(toAppStatus(status));
      setHistory(hist);
      setFeedback(fb);
      setSelectedDoc(prev => (prev ? docs.find(d => d.id === prev.id) ?? null : null));
    } catch (err) {
      console.error('Failed to refresh:', err);
      setError('Could not load data from the app.');
    }
  }, []);

  useEffect(() => {
    refreshAll();
  }, [refreshAll]);

  const handleImport = useCallback(async () => {
    console.log('Import triggered - use window.knowledgeBase.documents.import(filePath)');
  }, []);

  const handleAskQuestion = useCallback(async (question: string) => {
    setError(null);
    try {
      await window.knowledgeBase.qa.ask(question);
      // Re-read persisted history so the view is exactly what survives a restart.
      setHistory(await window.knowledgeBase.qa.history());
      setAppStatus(toAppStatus(await window.knowledgeBase.indexing.status()));
    } catch (err) {
      console.error('Q&A failed:', err);
      setError('The question could not be answered. Please try again.');
    }
  }, []);

  const handleRate = useCallback(async (answerId: string, rating: FeedbackRating) => {
    setError(null);
    try {
      const entry = await window.knowledgeBase.feedback.submit(answerId, rating);
      setFeedback(prev => [...prev.filter(f => f.answerId !== entry.answerId), entry]);
    } catch (err) {
      console.error('Feedback failed:', err);
      setError('Your rating could not be saved.');
    }
  }, []);

  const handleReset = useCallback(async () => {
    setError(null);
    try {
      await window.knowledgeBase.app.reset();
    } catch (err) {
      console.error('Reset failed:', err);
      setError('Reset failed.');
    }
    setSelectedDoc(null);
    await refreshAll();
  }, [refreshAll]);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100vh' }}>
      <header style={{
        padding: '12px 20px',
        background: '#16213e',
        borderBottom: '1px solid #0f3460',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
      }}>
        <h1 style={{ fontSize: '18px', fontWeight: 600 }}>Knowledge Base</h1>
        <div style={{ display: 'flex', gap: '8px', alignItems: 'center' }}>
          <button onClick={refreshAll} style={headerButton}>
            Refresh
          </button>
          <ResetButton onReset={handleReset} />
        </div>
      </header>

      <div style={{ display: 'flex', flex: 1, overflow: 'hidden' }}>
        {/* Left panel: Document list */}
        <div style={{
          width: '280px',
          borderRight: '1px solid #0f3460',
          display: 'flex',
          flexDirection: 'column',
          background: '#16213e',
        }}>
          <div style={{
            padding: '10px 16px',
            borderBottom: '1px solid #0f3460',
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
          }}>
            <span style={{ fontSize: '13px', fontWeight: 500, color: '#a0a0c0' }}>
              Documents ({documents.length})
            </span>
            <button
              onClick={handleImport}
              style={{
                padding: '4px 10px',
                background: '#533483',
                color: '#fff',
                border: 'none',
                borderRadius: '3px',
                cursor: 'pointer',
                fontSize: '12px',
              }}
            >
              + Import
            </button>
          </div>
          <DocumentList
            documents={documents}
            onSelect={setSelectedDoc}
            selectedId={selectedDoc?.id ?? null}
          />
        </div>

        {/* Right panel: selected document (if any) above the conversation */}
        <div style={{ flex: 1, display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>
          {selectedDoc && (
            <div style={{ maxHeight: '40%', overflow: 'auto', padding: '16px 20px', borderBottom: '1px solid #0f3460', position: 'relative' }}>
              <button
                type="button"
                aria-label="Close document"
                onClick={() => setSelectedDoc(null)}
                style={{ ...headerButton, position: 'absolute', top: '12px', right: '16px', padding: '2px 8px' }}
              >
                ✕
              </button>
              <DocumentDetail document={selectedDoc} />
            </div>
          )}
          <QuestionPanel
            history={history}
            ratings={ratings}
            onAsk={handleAskQuestion}
            onRate={handleRate}
            error={error}
          />
        </div>
      </div>

      <StatusBar status={appStatus} />
    </div>
  );
}

